#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
    virtual void speak() const { cout << name << "：喵～" << endl; }
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
    void speak() const override { cout << name << "：本喵是橘猫，喵喵喵！" << endl; }
    void eatSnack() const { cout << name << "：这条小鱼干归本喵！" << endl; }
};

class TabbyCat : public Cat {
public:
    TabbyCat(const string& n) : Cat(n) {}
    void speak() const override { cout << name << "：本喵是狸花猫，喵呜～" << endl; }
};

int main() {
    int kind = 0;
    cin >> kind;

    OrangeCat o("{who}");
    TabbyCat t("{other}");
    Cat* p = &t;
    if (kind == 1) p = &o;

    p->speak();

    return 0;
}

